/**
 * Shipsmall cursor by JMARIANI - https://store.kde.org/p/999209/
 * */

const frames = ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""].map(b64 => "data:image/png;base64," + b64);
const delay = 40;
const hotX = 0, hotY = 0;

const cursorEl = document.getElementById('cursor');
let frameIndex = 0;
let mouseX = window.innerWidth / 2;
let mouseY = window.innerHeight / 2;

frames.forEach(src => { const i = new Image(); i.src = src; });

function positionCursor() {
    cursorEl.style.transform = `translate(${mouseX - hotX}px, ${mouseY - hotY}px)`;
}

window.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;
    positionCursor();
});

function tick() {
    cursorEl.src = frames[frameIndex];
    frameIndex = (frameIndex + 1) % frames.length;
}

tick();
positionCursor();
setInterval(tick, delay);